def preflight(data):
 tls=all(x['exit_code']==0 and x['stdout'].strip()=='1'for x in data['target_tls_probes'])
 busy=data['target_busy'];queue=data['target_queue'];version=data['target_version'];capacity=busy['state']=='0'and 0<=float(busy['lastvalue'])<100 and queue['state']=='0'and queue['lastvalue']=='0'and version['lastvalue']=='7.0.32'
 old=data['old_proxy'];target=data['target_proxy'];own=data['configuration_ownership'];synced=all(h['proxyid']==old['proxyid']and h['monitored_by']=='1'and own[old['name']][h['hostid']]==1 and own[target['name']][h['hostid']]==0 for h in data['host_rows']);active=all(c['ServerActive']==data['old_active_endpoint']for c in data['agent_configs'])
 return dict(ready=tls and capacity and synced and active,tls_verified=tls,target_capacity_observed=capacity,central_configuration_synced=synced,active_targets_still_old=active,production_scale_capacity_validated=False)
def migrate(api,host,target,agent_config):
 api('host.update',{'hostid':host['hostid'],'monitored_by':1,'proxyid':target['proxyid']})
 return {'ServerActive':target['active_endpoint']}
def audit(data):
 rows=data['hosts'];target=data['target_proxy'];old=data['old_proxy'];own=data['ownership'];assigned=all(r['host']['monitored_by']=='1'and r['host']['proxyid']==target['proxyid']for r in rows);active=all(r['agent_config']['ServerActive']==target['active_endpoint']for r in rows);synced=all(own[old['name']][r['host']['hostid']]==0 and own[target['name']][r['host']['hostid']]==1 for r in rows);fresh=all(r['active_item']['lastvalue']==r['current_source_value']for r in rows);continuous=all(set(r['known_source_values'])<={h['value']for h in r['history']}for r in rows);history={(h['itemid'],h['clock'],h['ns'],h['value'])for r in rows for h in r['history']};residual=all((h['itemid'],h['clock'],h['ns'],h['value'])in history for h in data['old_proxy_residual_rows'])
 return dict(all_assigned_target=assigned,all_active_targets_target=active,central_configuration_synced=synced,all_latest_values_fresh=fresh,observed_history_continuous=continuous,old_residual_rows_delivered=residual,migration_complete=assigned and active and synced and fresh and continuous and residual,production_scale_capacity_validated=False)

容量常量不可通过：两个明确raw-SHA派生unit分别隔离busy=100和queue=1，要求容量观测门槛与ready均False；不冒称真实硬件/HTTP异常。

