 assert hashlib.sha256(raw).hexdigest()==PROFILE_SHA,'native runtime profile changed'
 profile=json.loads(raw)
 for tool in profile['tools']:assert hashlib.sha256(pathlib.Path(tool['path']).read_bytes()).hexdigest()==tool['sha256'],'native tool changed: '+tool['path']
 for row in profile['database_template_manifest']:
  path=pathlib.Path(profile['database_template'])/row['path'];assert path.stat().st_size==row['bytes'] and hashlib.sha256(path.read_bytes()).hexdigest()==row['sha256'],'native database template changed: '+row['path']
 return PROFILE_SHA

def read_json(path):return json.loads(pathlib.Path(path).read_text())
def free_port(bounded=False):
 for _ in range(100):
  with socket.socket()as sock:
   try:sock.bind(('127.0.0.1',20000+secrets.randbelow(3000)if bounded else 0));return sock.getsockname()[1]
   except OSError:pass
 raise AssertionError('No free owned loopback port in the native supported range')
def wait(fn,seconds=15):
 deadline=time.monotonic()+seconds;last=None
 while time.monotonic()<deadline:
  last=fn()
  if last:return last
  time.sleep(.1)
 raise AssertionError('Native bounded observation not satisfied: '+repr(last))
