 with urllib.request.build_opener(urllib.request.ProxyHandler({})).open(req,timeout=5)as response:return json.load(response)
def proc_identity(pid):
 try:
  p=pathlib.Path('/proc')/str(pid);text=(p/'stat').read_text().rsplit(')',1)[1].split();return {'pid':pid,'start_ticks':text[19],'state':text[0],'cwd':str((p/'cwd').resolve())}
 except(FileNotFoundError,PermissionError,ProcessLookupError):return None
def child_identities(pid):
 out=[]
 try:children=[int(x)for x in pathlib.Path('/proc/'+str(pid)+'/task/'+str(pid)+'/children').read_text().split()]
 except(FileNotFoundError,PermissionError):return out
 for child in children:
  identity=proc_identity(child)
  if identity:out.append(identity);out.extend(child_identities(child))
