class Node:
 def __init__(self,owner,kind,args,directory,process_env=None):
  self.owner=owner;self.kind=kind;self.logs=[];self.stopped=False;self.args=[str(x)for x in args];self.proc=subprocess.Popen(self.args,cwd=directory,env=process_env or env(),stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True);owner.nodes.append(self);owner.commands.append({'kind':kind,'argv':self.args,'pid':self.proc.pid})
  def reader():
   for line in self.proc.stdout:
    self.logs.append(line)
    if len(self.logs)>80:self.logs.pop(0)
  self.thread=threading.Thread(target=reader,daemon=True);self.thread.start()
 def alive(self):assert self.proc.poll()is None,self.kind+' exited: '+''.join(self.logs)[-2600:]
 def stop(self):
  descendants=child_identities(self.proc.pid)
  if not self.stopped:
   if self.proc.poll()is None:
    self.proc.terminate()
    try:self.proc.wait(timeout=15)
    except subprocess.TimeoutExpired:self.proc.kill();self.proc.wait(timeout=4)
   self.thread.join(timeout=4);self.proc.stdout.close();self.stopped=True
  # Parent normally reaps its native workers. Never signal a reused or foreign PID.
  remaining=[]
  for old in descendants:
   current=proc_identity(old['pid'])
   if current and current['start_ticks']==old['start_ticks']:
    assert pathlib.Path(current['cwd']).is_relative_to(self.owner.root)
    if current['state']!='Z':os.kill(old['pid'],15)
    remaining.append(old)
  deadline=time.monotonic()+4
  while remaining and time.monotonic()<deadline:
   remaining=[x for x in remaining if (p:=proc_identity(x['pid']))and p['start_ticks']==x['start_ticks']];time.sleep(.05)
  return {'kind':self.kind,'pid':self.proc.pid,'exit_code':self.proc.returncode,'reaped':self.proc.poll()is not None,'reader_stopped':not self.thread.is_alive(),'native_children_observed':descendants,'native_children_remaining':remaining}
